import{_ as t,o,c as r,a6 as a}from"./chunks/framework.ZMCvXf1_.js";const u=JSON.parse('{"title":"noorm secret","description":"","frontmatter":{},"headers":[],"relativePath":"cli/secret.md","filePath":"cli/secret.md"}'),s={name:"cli/secret.md"};function n(i,e,c,d,l,h){return o(),r("div",null,[...e[0]||(e[0]=[a(`<h1 id="noorm-secret" tabindex="-1">noorm secret <a class="header-anchor" href="#noorm-secret" aria-label="Permalink to “noorm secret”">​</a></h1><p>Manage <strong>config-scoped local secrets</strong> — values stored on disk in <code>.noorm/state/state.enc</code>, tied to a single config, and never shared with the rest of the team. This is one of three places a secret value can live; see <a href="#which-tier">Which tier?</a> below before reaching for it.</p><h2 id="subcommands" tabindex="-1">Subcommands <a class="header-anchor" href="#subcommands" aria-label="Permalink to “Subcommands”">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>Purpose</th></tr></thead><tbody><tr><td><code>noorm secret set &lt;key&gt; [value]</code></td><td>Store a secret for the active or named config</td></tr><tr><td><code>noorm secret list</code></td><td>List secret keys for a config (values never shown)</td></tr><tr><td><code>noorm secret rm &lt;key&gt;</code></td><td>Remove a secret from a config</td></tr></tbody></table><h2 id="flags" tabindex="-1">Flags <a class="header-anchor" href="#flags" aria-label="Permalink to “Flags”">​</a></h2><p>Common to every subcommand:</p><ul><li><code>--config &lt;name&gt;</code> / <code>-c &lt;name&gt;</code> — target a config other than the active one</li><li><code>--json</code> — emit machine-readable JSON on stdout</li></ul><p><code>secret set</code> additionally accepts:</p><ul><li><code>--stdin</code> — read the value from stdin instead of argv, so it never reaches the process table, shell history, or a <code>set -x</code> trace. Omit the positional value when you pass it.</li><li><code>--yes</code> / <code>-y</code> — confirm the write on a config whose <code>secret:write</code> access is a confirm cell (an <code>operator</code> user role). Without it the command exits non-zero.</li></ul><p><code>secret rm</code> additionally requires:</p><ul><li><code>--yes</code> / <code>-y</code> — confirm the deletion; omitted, the command exits non-zero without deleting</li></ul><h2 id="which-tier" tabindex="-1">Which tier? <a class="header-anchor" href="#which-tier" aria-label="Permalink to “Which tier?”">​</a></h2><p>noorm resolves <code>$.secrets.KEY</code> in a template from three tiers, config-local first:</p><table tabindex="0"><thead><tr><th>Tier</th><th>Command</th><th>Scope</th><th>Shared with team?</th></tr></thead><tbody><tr><td>Config-local</td><td><code>noorm secret set</code></td><td>One config</td><td>No — per-user, per-machine</td></tr><tr><td>Global-local</td><td>TUI only (<code>noorm ui</code> → Settings → Secrets)</td><td>Every config on this machine</td><td>No — per-user, per-machine</td></tr><tr><td>Vault</td><td><a href="./../guide/environments/vault.html"><code>noorm vault set</code></a></td><td>Every config, every teammate</td><td>Yes — encrypted in the database</td></tr></tbody></table><p>If a value should be different for you than for the rest of the team, it belongs in <code>noorm secret</code> (or the TUI&#39;s global-local screen). If it should be the same for everyone — CI included — it belongs in <code>noorm vault set</code>. <code>noorm secret set</code> on a value the whole team needs is the mistake this page exists to prevent: it lands in your local <code>state.enc</code> only, so a teammate or a CI runner resolving the same key finds nothing and either fails loudly (a missing secret now throws — see <a href="./../guide/sql-files/templates.html">Templates</a>) or silently picks up a stale vault value instead of the one you just set.</p><p>See <a href="./../guide/environments/secrets.html">Secrets</a> for config-scoped vs. global-local, and <a href="./../guide/environments/vault.html">Vault</a> for the full three-tier resolution hierarchy and team-provisioning workflow.</p><h2 id="examples" tabindex="-1">Examples <a class="header-anchor" href="#examples" aria-label="Permalink to “Examples”">​</a></h2><pre><code>noorm secret set API_KEY &quot;sk-live-...&quot;
echo &quot;$API_KEY&quot; | noorm secret set API_KEY --stdin
noorm secret set DB_PASSWORD &quot;secret123&quot; --config prod
noorm secret set API_KEY &quot;sk-live-...&quot; --json

noorm secret list
noorm secret list --config staging --json

noorm secret rm OLD_KEY --yes
noorm secret rm OLD_KEY --yes --config prod
</code></pre><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to “Related”">​</a></h2><ul><li><a href="./settings-secret.html"><code>noorm settings secret</code></a> — edits which secrets a stage <em>requires</em>, not their values.</li><li><a href="./../guide/environments/secrets.html">Secrets guide</a> — full CLI + TUI workflow.</li><li><a href="./../guide/environments/vault.html">Vault guide</a> — team-shared secrets and CI provisioning.</li></ul>`,20)])])}const f=t(s,[["render",n]]);export{u as __pageData,f as default};
